window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3608b5aafa36a683"]={"versions": [{"id": "FIG-3608b5aafa36a683", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Speicherlayout-Diagramm im Kontext des AUTOSAR Basic Software Moduls NVRAM Manager (NvM). Das Diagramm stellt den logischen Aufbau und die Segmentierung eines NV-Blocks dar, wie er vom NvM verwaltet und an die unterlagerte Memory Abstraction Interface (MemIf) bzw. Peripherietreiber weitergegeben wird. Es visualisiert nicht das physische Speicherlayout im Zielmedium, sondern die logische Strukturzusammensetzung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert drei vertikal angeordnete Schichten/Segmente eines NV-Blocks:</p>\n<ul class=\"fig-list\">\n<li><strong>NV block Header (optional)</strong>: Vorangestellter Kopfdatenbereich (grau hinterlegt), optional konfigurierbar.</li>\n<li><strong>NV block data</strong>: Zentraler Nutzdatenbereich (hellblau hinterlegt), verpflichtender Kernbestandteil des Blocks.</li>\n<li><strong>NV block CRC (optional)</strong>: Nachgestellter Prüfsummenbereich (grau hinterlegt) zur Datenintegritätsprüfung, optional konfigurierbar.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenstrukturdarstellung; kein dynamischer Sequenzablauf dargestellt. Der NvM assembliert beim Schreibvorgang den Block aus den Nutzdaten (sowie optional Header und berechneter CRC) bzw. zerlegt und validiert diesen beim Lesevorgang (Prüfung der optionalen CRC und Auswertung des optionalen Headers vor Bereitstellung der Nutzdaten an die Applikation/RAM-Block).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die logische Paketierung eines NV-Blocks für BSW-Entwickler und Konfiguratoren:</p>\n<ul class=\"fig-list\">\n<li>Nutzdaten (<code>NV block data</code>) sind stets vorhanden.</li>\n<li>Das Vorhandensein von <code>NV block Header</code> und <code>NV block CRC</code> ist konfigurierbar (optional).</li>\n<li>Bei aktivierter CRC-Berechnung ist die CRC dem Nutzdatenbereich logisch nachgestellt.</li>\n<li>Entsprechend der Bildunterschrift spiegelt dieses Layout die logische Anordnung des NV-Blocks wider und entspricht nicht zwingend dem physischen Layout im nichtflüchtigen Speicher (z. B. Flash/EEPROM Alignment, Treiber-spezifische Header oder Redundanzen).</li>\n</ul>"}, {"id": "FIG-efc48406bbf71680", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturschaubild / Speicherlayout-Diagramm im Kontext des AUTOSAR Basic Software Moduls NVRAM Manager (NvM). Das Diagramm stellt den logischen Aufbau und die Segmentierung eines NV-Blocks dar, wie er vom NvM verwaltet und an die unterlagerte Memory Abstraction Interface (MemIf) bzw. Peripherietreiber weitergegeben wird. Es visualisiert nicht das physische Speicherlayout im Zielmedium, sondern die logische Strukturzusammensetzung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert drei vertikal angeordnete Schichten/Segmente eines NV-Blocks:</p>\n<ul class=\"fig-list\">\n<li><strong>NV block Header (optional)</strong>: Vorangestellter Kopfdatenbereich (grau hinterlegt), optional konfigurierbar.</li>\n<li><strong>NV block data</strong>: Zentraler Nutzdatenbereich (hellblau hinterlegt), verpflichtender Kernbestandteil des Blocks.</li>\n<li><strong>NV block CRC (optional)</strong>: Nachgestellter Prüfsummenbereich (grau hinterlegt) zur Datenintegritätsprüfung, optional konfigurierbar.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenstrukturdarstellung; kein dynamischer Sequenzablauf dargestellt. Der NvM assembliert beim Schreibvorgang den Block aus den Nutzdaten (sowie optional Header und berechneter CRC) bzw. zerlegt und validiert diesen beim Lesevorgang (Prüfung der optionalen CRC und Auswertung des optionalen Headers vor Bereitstellung der Nutzdaten an die Applikation/RAM-Block).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die logische Paketierung eines NV-Blocks für BSW-Entwickler und Konfiguratoren:</p>\n<ul class=\"fig-list\">\n<li>Nutzdaten (<code>NV block data</code>) sind stets vorhanden.</li>\n<li>Das Vorhandensein von <code>NV block Header</code> und <code>NV block CRC</code> ist konfigurierbar (optional).</li>\n<li>Bei aktivierter CRC-Berechnung ist die CRC dem Nutzdatenbereich logisch nachgestellt.</li>\n<li>Entsprechend der Bildunterschrift spiegelt dieses Layout die logische Anordnung des NV-Blocks wider und entspricht nicht zwingend dem physischen Layout im nichtflüchtigen Speicher (z. B. Flash/EEPROM Alignment, Treiber-spezifische Header oder Redundanzen).</li>\n</ul>"}], "trans": [{"from": "FIG-3608b5aafa36a683", "to": "FIG-efc48406bbf71680", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
